// Design Ref: §4.1 daily-publish node 4 — 키워드 수집
// ponytail: 네이버 데이터랩 Open API는 카테고리별 트렌드 검색어만 제공하고
// 롱테일 키워드 자동완성은 공식 API가 없어 크롤링이 필요하다.
// 1차 구현은 운영자가 n8n Set 노드/Static Data에 미리 넣어둔 후보 목록에서
// 순차 선택하는 최소 버전으로 시작하고, 후보 소진 시 운영자가 보충한다.
// 업그레이드 경로: 네이버 자동완성 비공식 엔드포인트 크롤링 노드 추가.
const staticData = $getWorkflowStaticData('global');
const pool = staticData.keywordPool || [];
if (pool.length === 0) {
  throw new Error('keywordPool이 비었습니다. Static Data에 후보 키워드를 채워주세요.');
}
const keyword = pool.shift();
staticData.keywordPool = pool;
return [{ json: { keyword } }];

// Design Ref: §4.1 node 5 - NIM(chat) 응답에서 본문 텍스트 + 이미지 프롬프트 추출
const resp = $input.first().json;
let text = resp?.choices?.[0]?.message?.content;
if (!text) {
  throw new Error('NIM 응답에서 본문을 추출하지 못했습니다: ' + JSON.stringify(resp).slice(0, 300));
}
// 제로폭 문자 제거(네이버 에디터 줄바꿈/품질체크 오염 방지)
text = text.replace(/[​-‍﻿]/g, '');
// 마지막 IMG: 줄 = 영어 이미지 프롬프트 (본문에서 분리)
let imagePrompt = '';
text = text.replace(/^s*IMG:s*(.+)$/gm, (_, p) => { imagePrompt = p.trim(); return ''; });
// 모델이 마크다운 기호를 섞어도 네이버 에디터엔 일반 텍스트로 들어가게 제거
text = text.replace(/^s*-{3,}s*$/gm, '').replace(/[#*]/g, '');
// 소제목(짧은 줄)이 앞 문단에 붙지 않도록 앞에 빈 줄 보장(첫 줄=제목 제외)
text = text.trim().split('\n').map((l, i, a) => (i > 1 && l.trim() && l.trim().length <= 40 && !/[.!]$/.test(l.trim()) && a[i - 1].trim() ? '\n' + l : l)).join('\n');
return [{ json: { ...$('키워드 수집').first().json, body: text.trim(), imagePrompt } }];

// Design Ref: §4.4.1 — 발행전 체크리스트 100점제 (임계 70) + 하드 Fail
const prev = $('다듬기 가드').first().json;
const body = prev.body;
const keyword = prev.keyword;
const imageResp = $input.first().json;
const b64 = imageResp?.artifacts?.[0]?.base64;
const imageUrl = b64 ? `data:image/jpeg;base64,${b64}` : null;

const THRESHOLD = 70;
const lines = body.split('\n').map(l => l.trim());
const title = lines[0] || '';
const rest = lines.slice(1).filter(Boolean);
const n = body.replace(/\s/g, '').length;
const isSub = l => l.length <= 40 && !/[.!]$/.test(l);
const subs = rest.filter(isSub);
const paras = body.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
const toks = keyword.split(/\s+/).filter(t => t.length >= 2);
const kwCount = Math.max(0, ...toks.map(t => body.split(t).length - 1));
const sentences = body.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(s => s.length > 10);
const dupRatio = sentences.length ? 1 - new Set(sentences).size / sentences.length : 0;
const transHits = (body.match(/에 의해|것입니다|라고 할 수 있|에 대해서|를 통해|하는 것이 중요합니다/g) || []).length;
const titleTok = title.split(/\s+/).filter(t => t.length >= 2);
const titleCovered = titleTok.length ? titleTok.filter(t => body.slice(title.length).includes(t)).length / titleTok.length : 0;
const lastPara = paras[paras.length - 1] || '';

const fails = [];
if (/https?:\/\/|www\./i.test(body)) fails.push('외부링크');
if (/완벽\s*가이드|총정리|꿀팁\s*Zip/i.test(title)) fails.push('금지제목어');
if (!imageUrl) fails.push('이미지없음');

const breakdown = {
  length: n >= 1200 && n <= 1800 ? 15 : n >= 960 && n <= 2160 ? 8 : 0,
  title: (title.includes(keyword.split(/\s+/)[0]) ? 8 : 0) + (title.length >= 15 && title.length <= 40 ? 6 : 0) + (titleCovered >= 0.5 ? 6 : 0),
  structure: (subs.length >= 3 ? 10 : subs.length >= 1 ? 5 : 0) + (subs.some(s => /[?]|나요|까요|일까/.test(s)) ? 5 : 0) + (paras.filter(p => p.length <= 250).length / paras.length >= 0.7 ? 5 : 0),
  keyword: kwCount >= 3 && kwCount <= 15 ? 15 : (kwCount >= 1 && kwCount <= 20 ? 8 : 0),
  quality: (dupRatio === 0 ? 8 : dupRatio < 0.1 ? 4 : 0) + (/\d/.test(body) ? 6 : 0) + (transHits <= 2 ? 6 : transHits <= 5 ? 3 : 0),
  cta: (lastPara.length >= 20 && !isSub(lastPara) ? 5 : 0) + (fails.includes('외부링크') ? 0 : 5)
};
const score = Object.values(breakdown).reduce((a, b) => a + b, 0);
const passed = fails.length === 0 && score >= THRESHOLD;

return [{ json: { ...prev, imageUrl, checks: { score, threshold: THRESHOLD, breakdown, fails, chars: n, kwCount }, passed } }];

