// Design Ref: §4.1 node 8 — 제휴비중 게이트 (module-4)
// Plan FR-08: 로드맵 단계별 정보성/제휴성 비중(100/0 -> 80/20 -> 60~70/30~40)
// ponytail: 실제 쇼핑커넥트 링크 삽입은 아직 커넥트 미연동이라 범위 밖.
// 여기서는 isAffiliatePost 플래그만 결정해 Playwright 스크립트에 전달한다.
// 연동 후 업그레이드 경로: isAffiliatePost=true일 때 Playwright 스크립트가
// 셀러 제공 상품 이미지/링크를 본문에 삽입하도록 확장.
const staticData = $getWorkflowStaticData('global');

// 운영자가 게이트 통과 후 수동으로 전환하는 값 (Design §5.2 User Flow 참조)
if (!staticData.roadmapPhase) {
  staticData.roadmapPhase = '지수성장기';
}
const RATIO_BY_PHASE = {
  '준비기': 0,
  '지수성장기': 0,
  '최적화진입': 20,
  '운영': 35
};
const affiliateRatio = RATIO_BY_PHASE[staticData.roadmapPhase] ?? 0;
staticData.affiliateRatio = affiliateRatio;

const isAffiliatePost = Math.random() * 100 < affiliateRatio;

return [{
  json: {
    ...$input.first().json,
    roadmapPhase: staticData.roadmapPhase,
    affiliateRatio,
    isAffiliatePost
  }
}];

// Design Ref: §4.1 node 10 — 상태 기록, Plan FR-07 중복 발행 방지
const staticData = $getWorkflowStaticData('global');
staticData.lastPublishedDate = new Date().toISOString().slice(0, 10);
return $input.all();

// Design Ref: §4.4.3 — 다듬기 결과 가드: 변경률 50% 초과·결과 이상 시 원문 롤백
const orig = $('본문 추출').first().json;
const resp = $input.first().json;
let out = (resp?.choices?.[0]?.message?.content || '').replace(/[​-‍﻿]/g, '').replace(/[#*]/g, '').trim();
const a = orig.body, b = out;
let polish = 'applied', rate = 0;
if (!b || b.length < a.length * 0.7 || b.length > a.length * 1.3) {
  polish = 'rollback:length';
} else {
  // Levenshtein (2행), 변경률 = 거리 / 긴 쪽 길이
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  rate = prev[b.length] / Math.max(a.length, b.length);
  if (rate > 0.5) polish = 'rollback:rate';
  else if (rate > 0.3) polish = 'warn:rate';
}
const body = polish.startsWith('rollback') ? a : b;
return [{ json: { ...orig, body, polish, changeRate: Math.round(rate * 1000) / 1000 } }];
